  benchmark::RegisterBenchmark("OctreeCompression/Lossless/Decode", BM_OctreeCompressionLosslessDecode)
      ->RangeMultiplier(4)
      ->Range(1024, 65536)
      ->Unit(benchmark::kMillisecond);

  benchmark::Initialize(&argc, argv);
  benchmark::RunSpecifiedBenchmarks();
  benchmark::Shutdown();
}

